use vstd::prelude::*;

verus! {

fn min_array(a: &Vec<i32>) -> (result: i32)
    requires
        // array is non‐empty
        a.len() > 0,
    ensures
        // result is ≤ every element
        forall |k: usize| k < a.len() ==> result <= a[k],
        // result is equal to at least one element
        exists |k: usize| k < a.len() && result == a[k],
{
    // initialize min to first element
    let mut min: i32 = a[0];
    // we'll scan from index 1 up to a.len()
    let mut i: usize = 1;
    while i < a.len()
        invariant
            // scan index stays within bounds
            i <= a.len(),
            // up to, but not including, i, min is ≤ each element
            forall |k: usize| k < i ==> min <= a[k],
            // and min is equal to at least one element among 0..i
            exists |k: usize| k < i && min == a[k],
        decreases
            // we make progress toward finishing the scan
            a.len() - i,
    {
        let v: i32 = a[i];
        if v < min {
            // after this update, new min is v,
            // which is ≤ all previous elements because
            // v < old min ≤ each a[k] for k<i
            min = v;
        }
        i += 1;
    }
    // at termination, i == a.len(),
    // so the invariants show min is the minimum over all indices
    min
}

} // verus!

